 h3{font-size:15px;margin:0 0 9px}.comparison p{font-size:13px;color:#637365;line-height:1.8;margin:0 0 8px}.comparison small{font-size:11px;color:#839183;line-height:1.7;display:block}.examples{border-top:1px solid #edf0e9;margin-top:17px;padding-top:16px;color:#6e7c6f}.examples summary{cursor:pointer;font-size:12px;font-weight:700}.examples p{font-size:12px;line-height:1.7}.crash-scale footer{color:#8c9489;font-size:11px;line-height:1.7;margin-top:16px}.crash-scale footer a{color:#587c6a;text-decoration:none}@media(max-width:760px){.crash-scale>.section-summary{align-items:start;flex-direction:column}.top-metrics,.comparison{grid-template-columns:1fr}.scale-body,.crash-scale>.section-summary{padding:17px}.ladder-labels{font-size:9px}.top-metrics b{font-size:21px}}
.amplitude-panel{margin-top:16px;border:1px solid #ece5d9;border-radius:12px;background:#fffdf9;padding:17px}.amplitude-heading{display:flex;justify-content:space-between;align-items:center;gap:12px}.amplitude-heading h3{font-size:15px;margin:0 0 4px}.amplitude-heading p,.amplitude-method{font-size:11px;color:#7b877c;line-height:1.7;margin:0}.amplitude-heading strong{white-space:nowrap;font-size:12px;color:#a65345;background:#f9eee7;border-radius:20px;padding:7px 11px}.amplitude-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin:13px 0}.amplitude-metrics article{min-width:0;background:white;border:1px solid #eeeae3;border-radius:9px;padding:13px}.amplitude-metrics small,.amplitude-metrics span,.amplitude-metrics em{display:block;font-size:11px;line-height:1.5}.amplitude-metrics small{color:#829080}.amplitude-metrics b{display:block;color:#4c624e;font-size:21px;margin:4px 0}.amplitude-metrics span{color:#6d796e}.amplitude-metrics em{font-style:normal;color:#879287;margin-top:6px}.amplitude-metrics em.active{color:#b55b4a;font-weight:700}@media(max-width:760px){.amplitude-heading{align-items:flex-start;flex-direction:column}.amplitude-metrics{grid-template-columns:1fr}}
</style>
